# Import of required libraries
import skyramp
import os
import time

from SkyrampUtils import (
    create_recipe,
    delete_recipe,
    get_recipe_stats,
)


# URL for test requests
URL_localhost = skyramp.get_base_url("SKYRAMP_TEST_BASE_URL", "http://localhost:9000")


def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    # Definition of authentication header
    headers = {}
    if os.getenv("SKYRAMP_TEST_TOKEN") is not None:
        headers["Authorization"] = "Bearer " + os.getenv("SKYRAMP_TEST_TOKEN")

    recipes_POST_response = create_recipe(client, headers, "Recipe Stats Deleted Check")

    stats_GET_response = get_recipe_stats(client, headers, "recipe-stats-deleted-check")

    assert skyramp.get_response_value(stats_GET_response, "ingredientCount") == 1
    assert skyramp.get_response_value(stats_GET_response, "instructionCount") == 1
    assert skyramp.get_response_value(stats_GET_response, "toolCount") == 0
    assert skyramp.get_response_value(stats_GET_response, "tagCount") == 0
    assert skyramp.get_response_value(stats_GET_response, "categoryCount") == 0

    recipe_stats_deleted_check_DELETE_response = delete_recipe(client, headers, "recipe-stats-deleted-check")

    assert skyramp.get_response_value(recipe_stats_deleted_check_DELETE_response, "slug") == "recipe-stats-deleted-check"
    assert skyramp.get_response_value(recipe_stats_deleted_check_DELETE_response, "name") == "Recipe Stats Deleted Check"
    assert len(skyramp.get_response_value(recipe_stats_deleted_check_DELETE_response, "id")) == 36 and skyramp.get_response_value(recipe_stats_deleted_check_DELETE_response, "id").count("-") == 4

    stats_GET_1_response = get_recipe_stats(client, headers, "recipe-stats-deleted-check", 404)

    assert skyramp.get_response_value(stats_GET_1_response, "detail.message") == "No Entry Found"
    assert skyramp.get_response_value(stats_GET_1_response, "detail.error") is True
    assert skyramp.check_schema(stats_GET_1_response, '{"detail": {"message": "No Entry Found", "error": true, "exception": null}}')
    assert skyramp.get_response_value(stats_GET_1_response, "ingredientCount") is None


if __name__ == "__main__":
    test_integration()
